def audit(url,protected_ref,object_id,previous_clone):
    parsed=urllib.parse.urlsplit(url)
    try:port=parsed.port
    except ValueError as error:raise ValueError('endpoint port') from error
    if parsed.scheme!='git' or parsed.hostname!='127.0.0.1' or not 1<=port<=65535 or parsed.username or parsed.password or parsed.query or parsed.fragment or not re.fullmatch(r'/[A-Za-z0-9_.-]{1,64}\.git',parsed.path):raise ValueError('loopback Git endpoint only')
    if not isinstance(protected_ref,str) or chr(0) in protected_ref or not isinstance(object_id,str) or not re.fullmatch(r'(?:[0-9a-f]{40}|[0-9a-f]{64})',object_id):raise ValueError('ref/OID')
    env={key:value for key,value in os.environ.items() if not key.startswith('GIT_')}
    env.update(GIT_CONFIG_NOSYSTEM='1',GIT_CONFIG_GLOBAL=os.devnull,GIT_TERMINAL_PROMPT='0',GIT_ALLOW_PROTOCOL='git')
    def git(*args,cwd=None):
        return subprocess.run(['git',*args],cwd=cwd,env=env,capture_output=True,text=True,encoding='utf8',timeout=4)
    if git('check-ref-format',protected_ref).returncode:raise ValueError('invalid full ref')
    clone=pathlib.Path(previous_clone)
    if clone.is_symlink() or not clone.is_dir() or (clone/'.git').is_symlink() or not (clone/'.git').is_dir():raise ValueError('previous clone required')
    metadata=(clone/'.git').resolve();probe=git('--git-dir='+str(metadata),'cat-file','-e',object_id+'^{commit}')
    if probe.returncode not in (0,1):raise ValueError('prior clone inspection failed')
    advertised=git('ls-remote','--refs',url)
    if advertised.returncode:raise RuntimeError('Git endpoint unavailable')
    refs={line.split('\t',1)[1] for line in advertised.stdout.splitlines() if len(line.split('\t',1))==2}
    with tempfile.TemporaryDirectory(prefix='of-git-hide-') as directory:
        fresh=pathlib.Path(directory);initialized=git('init','--quiet',str(fresh))
        if initialized.returncode:raise RuntimeError('fresh client init failed')
        byref=git('-C',str(fresh),'fetch','--no-tags',url,protected_ref)
        byoid=git('-C',str(fresh),'fetch','--no-tags',url,object_id)
        if byref.returncode not in (0,1,128) or byoid.returncode not in (0,1):raise RuntimeError('unexpected Git protocol result: ref='+str(byref.returncode)+'/'+byref.stderr[-400:]+' oid='+str(byoid.returncode)+'/'+byoid.stderr[-400:])
    hidden=protected_ref not in refs;ref_denied=byref.returncode!=0;oid_denied=byoid.returncode!=0;old_copy=probe.returncode==0
    exposed=not ref_denied or not oid_denied or old_copy
